  { role: "开放讨论区", count: 1, minimumFootprint: [3.5, 3.4], adjacency: "西南侧；四把座椅围绕讨论桌，座椅中心距桌心1.05" },
  { role: "会客阅读区", count: 1, minimumFootprint: [4.2, 4.1], adjacency: "东侧；沙发面向艺术矮柜，茶几距沙发前沿0.50" },
  { role: "咖啡补给区", count: 1, minimumFootprint: [2.0, 3.0], adjacency: "西北侧；咖啡机置于操作台，正面保留1.10操作空间" },
  { role: "连续通行区", count: 1, minimumFootprint: [1.1, 1.1], adjacency: "四周至少1.15宽环路；南入口接中央1.50宽通道" }
];
const zones = {
  circulation: { perimeterInset: 1.15, centralX: [-0.75, 0.75], centralZ: [-1.6, 4.8] },
  work: { center: [0, -2.9], enclosure: "open" },
  discussion: { center: [-3.55, 2.15], enclosure: "open" },
  lounge: { center: [4.25, 1.9], enclosure: "low-cabinet edge" },
  coffee: { center: [-5.75, -2.0], enclosure: "open" }
};
// All programmed activities are shared and daylight-compatible.
// No private room is invented: low furniture defines the zones without closing routes.
const contract = " Coordinate contract: Y+ is up, Z+ is the front/entrance direction, X+ is right.";
function family(key, name, prompt, dimensions, role = "functional") {
  api.requireAsset({ key, name, prompt: prompt + contract, dimensions, role });
}
function floor(key, name, x, z, dimensions, rotationY = 0, role = "functional") {
  return api.place({
    assetId: api.asset(key), name,
    position: api.roomPoint(x, z, 0),
    dimensions, rotationY, role
  });
}
function supported(key, name, parentId, dimensions, offset = [0, 0], role = "decor") {
  return api.attach({
    assetId: api.asset(key), name, parentId, kind: "supported",
    anchorY: "bottom", offset, dimensions, role
  });
}
function pendant(x, z, width) {
  api.place({
    assetId: api.asset("pendant"), name: "悬浮线性工作照明",
    position: api.ceilingPoint(x, z, 0.65, 0.15),
    dimensions: [width, 0.65, 0.16], role: "functional"
  });
}
