const openings = Array.isArray(api.room.openings) ? api.room.openings : [];
if (!openings.some(o => o.kind === "door" || o.type === "door")) {
  family("entrydoor", "入口玻璃门", "One modern black steel framed clear glass entrance door with a slim pull handle, closed door leaf and narrow frame, standalone door assembly", [1.35, 2.65, 0.12]);
  const openingId = api.opening({
    id: "loft-main-entry", kind: "door", wall: "south",
    offset: 0, bottom: 0, width: 1.35, height: 2.65
  });
  api.place({
    assetId: api.asset("entrydoor"), roomOpeningId: openingId,
    dimensions: [1.35, 2.65, 0.12], role: "functional"
  });
}

// Northern anchor: two complete workstations share one substantial table.
// Chairs face south; the monitors face north toward their users.
const desk = floor("desk", "双人创作主工作台", 0, -2.65, [5.1, 0.76, 1.15]);
for (const x of [-1.3, 1.3]) {
  floor("taskchair", "工作台配套人体工学椅", x, -3.8, [0.65, 1.12, 0.65]);
  api.place({
    assetId: api.asset("monitor"), name: "面向工作椅的显示器",
    position: api.roomPoint(x, -2.43, 0.76),
    rotationY: Math.PI, dimensions: [0.86, 0.51, 0.22], role: "functional"
  });
  supported("tasklamp", "工作位阅读灯", desk, [0.38, 0.56, 0.27], [x - 0.53, 0.1], "functional");
  supported("organizer", "工作位文具与笔记本", desk, [0.46, 0.06, 0.3], [x, -0.29]);
}
pendant(0, -2.65, 3.8);
const shelf = floor("shelf", "工作区开放资料架", 4.15, -3.65, [2, 1.3, 0.4]);
supported("books", "资料架顶层设计书", shelf, [0.44, 0.3, 0.23], [-0.57, 0]);
supported("sculpture", "资料架陶艺陈列", shelf, [0.3, 0.39, 0.23], [0.57, 0]);
floor("plant", "工作区绿植", 5.8, -3.6, [0.65, 1.65, 0.65], 0, "decor");

// Western service anchor: cabinet front faces the open central studio.
const coffee = floor("kitchen", "西侧咖啡操作台", -5.75, -2.35, [2.4, 0.94, 0.65], Math.PI / 2);
supported("espresso", "台面咖啡机", coffee, [0.45, 0.4, 0.36], [-0.55, 0], "functional");
supported("organizer", "咖啡区收纳盘", coffee, [0.46, 0.06, 0.3], [0.56, 0]);
floor("plant", "咖啡区端景绿植", -5.75, -0.45, [0.58, 1.47, 0.58], 0, "decor");

// Southwest: four seats form a genuine discussion constellation.
floor("rug", "讨论区薄编织地毯", -3.55, 2.15, [3.35, 0.015, 3.35], 0, "decor");
const meeting = floor("meeting", "四人圆形讨论桌", -3.55, 2.15, [1.6, 0.75, 1.6]);
for (const [dx, dz] of [[0, -1.08], [0, 1.08], [-1.08, 0], [1.08, 0]]) {
  floor("meetingchair", "围合讨论座椅", -3.55 + dx, 2.15 + dz,
    [0.53, 0.81, 0.56], Math.atan2(-dx, -dz));
}
supported("organizer", "讨论桌共享笔记盘", meeting, [0.46, 0.06, 0.3], [0, 0]);
pendant(-3.55, 2.15, 1.7);

// Eastern focal pair: caramel sofa faces a low gallery cabinet.
// Cabinet remains below seated sightlines and never becomes a partition wall.
floor("rug", "会客阅读区地毯", 4.25, 2.05, [3.85, 0.015, 3.7], 0, "decor");
const gallery = floor("cabinet", "沙发正对艺术陈列柜", 4.2, -0.12, [2.85, 0.7, 0.43]);
supported("sculpture", "会客区主陶艺雕塑", gallery, [0.42, 0.55, 0.3], [0.63, 0]);
supported("books", "艺术柜精选画册", gallery, [0.44, 0.3, 0.23], [-0.72, 0]);
floor("sofa", "面向艺术柜的皮革沙发", 4.2, 3.48, [2.8, 0.84, 0.95], Math.PI);
const table = floor("coffeetable", "沙发配套石质茶几", 4.2, 2.13, [1.6, 0.36, 0.75]);
supported("organizer", "茶几随手阅读盘", table, [0.46, 0.06, 0.3], [-0.35, 0]);
floor("armchair", "朝向会客中心的阅读单椅", 5.96, 1.18,
  [0.85, 0.88, 0.9], Math.atan2(4.2 - 5.96, 2.13 - 1.18));
const side = floor("sidetable", "沙发扶手旁边几", 2.37, 3.48, [0.5, 0.52, 0.5]);
supported("books", "边几设计读物", side, [0.3, 0.21, 0.19], [0, 0]);
floor("floorlamp", "沙发端部阅读灯", 6.0, 3.5, [0.42, 1.6, 0.42], Math.PI);
pendant(4.2, 2.1, 2.5);

// Wall layers are mounted only on spans not occupied by declared openings.
function spanAvailable(wall, offset, width, bottom, height) {
  return !openings.some(o => {
    if (o.wall !== wall) return false;
    const ow = Number.isFinite(o.width) ? o.width : 2.4;
    const oc = Number.isFinite(o.offset) ? o.offset : 0;
    const ob = Number.isFinite(o.bottom) ? o.bottom : 0;
    const oh = Number.isFinite(o.height) ? o.height : 3;
    return Math.abs(offset - oc) < (width + ow) / 2 + 0.2 &&
      bottom < ob + oh + 0.1 && bottom + height > ob - 0.1;
  });
}
let artPlaced = false;
for (const [wall, offset] of [["north", 0], ["west", 2.1], ["east", -2.4], ["south", -3.55]]) {
  if (artPlaced || !spanAvailable(wall, offset, 2.0, 1.9, 1.15)) continue;
  const frame = api.wallFrame(wall, offset, 1.9, 0.045);
  api.place({
    assetId: api.asset("art"), name: "工作室建筑几何主画",
    position: frame.point, facing: { direction: frame.inward },
    dimensions: [2.0, 1.15, 0.045], role: "decor"
  });
  artPlaced = true;
}
if (!artPlaced) {
  // Keep glazing unobstructed: the artwork becomes a smaller supported gallery object.
  supported("art", "艺术柜上的几何画", gallery, [0.72, 0.48, 0.045], [0, -0.1]);
}

function plan(api) {
  // 功能简表：角色、数量、最小占地、邻接关系。
  const brief = [
    { role: "主卧睡眠区", count: 1, footprint: [5.5, 5.0], adjacency: "床头背景、双床头柜、床尾长凳" },
    { role: "独立衣帽间", count: 1, footprint: [3.5, 4.7], adjacency: "主卧、真实门洞、衣柜和穿衣镜" },
    { role: "双人阅读区", count: 1, footprint: [3.9, 2.7], adjacency: "座椅相向、共用茶几、落地灯" },
    { role: "梳妆区", count: 1, footprint: [1.7, 2.4], adjacency: "梳妆桌、镜子、坐凳" },
    { role: "交通", count: 1, footprint: [1.0, 1.0], adjacency: "所有外门经连续周边通道连接主卧和衣帽间" }
  ];
  const zones = {
    circulation: { perimeterInset: 1.35, southCrossRoute: [0.55, 1.55] },
    dressing: { x: [-5.35, -1.85], z: [-4.4, 0.3], enclosure: "full-height" },
    sleeping: { x: [-1.1, 4.1], z: [-4.4, 0.5], enclosure: "open" },
    reading: { x: [-3.0, 1.1], z: [1.7, 4.5], enclosure: "open" },
    vanity: { x: [3.0, 5.25], z: [1.7, 4.5], enclosure: "open" }
  };
  const relation = {
    bedsideGap: 0.18,
    benchFromBed: 0.42,
    readingSeatFromTable: 1.14,
    vanitySeatFromDesk: 0.85,
    lampFromChair: 0.72
  };
  const suffix = " Coordinate contract: Y+ is up, Z+ is the front/entrance direction, X+ is right.";
  const definitions = [
    ["wall", "暖白隔墙", [1, 4, 0.14], "A single full height interior partition segment, warm ivory painted plaster, clean flush ends, subtle oak skirting, no openings.", "functional"],
    ["door", "衣帽间木门", [1.02, 2.65, 0.055], "One warm oak interior door leaf with a small brushed brass lever, plain flush wood grain, no frame.", "functional"],
    ["wardrobe", "橡木衣柜", [1.2, 2.85, 0.62], "One premium warm oak wardrobe with closed lower drawers and lightly reeded oak full height doors, small antique brass handles.", "functional"],
    ["bed", "布艺双人床", [2.25, 1.32, 2.45], "One inviting king bed with a rounded oatmeal upholstered headboard, ivory linen duvet, layered pillows, muted terracotta throw neatly draped over the foot, oak recessed feet.", "functional"],
    ["headpanel", "床头屏风", [4.7, 2.55, 0.18], "One freestanding bedroom headboard backdrop panel, warm oak perimeter frame with padded sand linen center, finished rear, restrained curved upper corners, concealed stable base.", "functional"],
    ["nightstand", "床头柜", [0.65, 0.55, 0.48], "One rounded warm walnut bedside cabinet with one drawer and an open lower shelf, small brass pull.", "functional"],
    ["tablelamp", "陶瓷台灯", [0.34, 0.53, 0.34], "One bedside lamp with a pale ochre ceramic base, pleated ivory linen shade and warm diffused light.", "functional"],
    ["rug", "羊毛地毯", [4.4, 0.025, 3.9], "One low pile ivory wool area rug with subtle sand and muted clay woven border, soft tactile texture, flat edges.", "decor"],
    ["bench", "床尾长凳", [1.65, 0.45, 0.48], "One bedroom bench with a softly upholstered caramel boucle seat, rounded walnut legs and a lower slatted shelf.", "functional"],
    ["chair", "阅读扶手椅", [0.86, 0.88, 0.88], "One generous softly rounded reading armchair upholstered in warm cream boucle, walnut legs, one muted rust lumbar cushion.", "functional"],
    ["sidetable", "圆茶几", [0.62, 0.48, 0.62], "One small round walnut side table with a honed cream travertine top and sturdy sculptural pedestal.", "functional"],
    ["floorlamp", "阅读落地灯", [0.46, 1.62, 0.46], "One slender aged brass reading floor lamp with a compact ivory fabric shade and a circular weighted base, warm light.", "functional"],
    ["vanity", "橡木梳妆台", [1.5, 0.78, 0.52], "One elegant oak dressing table with rounded front corners, two shallow drawers, ivory stone inset top and clear knee space.", "functional"],
    ["stool", "梳妆坐凳", [0.52, 0.47, 0.48], "One small oval upholstered vanity stool in muted rose linen with four tapered walnut legs.", "functional"],
    ["mirror", "台式梳妆镜", [0.66, 0.83, 0.16], "One freestanding arched tabletop vanity mirror with a thin aged brass frame and stable integral brass foot.", "functional"],
    ["fullmirror", "落地穿衣镜", [0.78, 1.9, 0.28], "One full length freestanding arched dressing mirror in a slim warm oak frame with a compact stable rear support.", "functional"],
    ["pendant", "纸艺吊灯", [1.0, 0.55, 1.0], "One large softly glowing ivory washi paper pendant lamp, flattened round organic shade, short brass ceiling stem.", "functional"],
    ["art", "抽象风景画", [1.3, 0.9, 0.045], "One framed abstract landscape artwork in muted terracotta, cream and sage, textured matte paper, slim oak frame.", "decor"],
    ["books", "床边书册", [0.3, 0.09, 0.23], "One neat stack of three linen bound books in warm neutral colors with understated blank spines.", "decor"],
    ["tray", "陶瓷茶盘", [0.38, 0.14, 0.27], "One oval ivory ceramic tea tray with two small handmade ceramic cups held neatly within its rim.", "decor"],
    ["plant", "室内绿植", [0.65, 1.3, 0.65], "One airy indoor olive plant in a rounded matte sand ceramic planter, restrained natural foliage.", "decor"],
    ["basket", "编织衣篮", [0.48, 0.58, 0.48], "One lidded woven natural seagrass laundry basket with a cream linen liner and small loop handles.", "functional"],
    ["box", "首饰收纳盒", [0.26, 0.12, 0.18], "One small closed walnut jewelry box with a subtle brass clasp and softly rounded corners.", "decor"]
  ];
  const dims = {};
  for (const [key, name, dimensions, prompt, role] of definitions) {
    dims[key] = dimensions;
    api.requireAsset({ key, name, dimensions, prompt: prompt + suffix, role });
  }
  function floor(key, name, x, z, angle = 0, dimensions) {
    return api.place({
      assetId: api.asset(key), name,
      position: api.roomPoint(x, z, 0),
      rotationY: angle,
      dimensions: dimensions || dims[key],
      role: definitions.find(d => d[0] === key)[4]
    });
  }
  function supported(key, parentId, offset, dimensions) {
    return api.attach({
      assetId: api.asset(key), parentId, kind: "supported",
      offset, dimensions: dimensions || dims[key],
      role: definitions.find(d => d[0] === key)[4]
    });
  }
  function partition(name, x, z, length, angle = 0) {
    return floor("wall", name, x, z, angle, [length, 4, 0.14]);
  }

  // 先建衣帽间。外侧周边走道宽至少1.35米；南侧门前整条横向通道保持空旷。
  const d = zones.dressing;
  const cx = (d.x[0] + d.x[1]) / 2;
  const cz = (d.z[0] + d.z[1]) / 2;
  partition("衣帽间北墙", cx, d.z[0], 3.5);
  partition("衣帽间西墙", d.x[0], cz, 4.7, Math.PI / 2);
  partition("衣帽间东墙", d.x[1], cz, 4.7, Math.PI / 2);
  // 南墙门洞[-3.47,-2.37]，净宽1.10米。
  partition("衣帽间南墙左段", -4.41, 0.3, 1.88);
  partition("衣帽间南墙右段", -2.11, 0.3, 0.52);
  api.place({
    assetId: api.asset("wall"), name: "衣帽间门楣",
    position: api.roomPoint(-2.92, 0.3, 2.72),
    dimensions: [1.1, 1.28, 0.14], role: "functional"
  });
  // 门扇向衣帽间内部开启90度，开启弧范围内不设家具。
  floor("door", "向内开启的衣帽间门", -2.39, -0.22, Math.PI / 2);

  // 衣帽间：柜体在西墙内侧，面向宽敞的试衣通道。
  for (const z of [-3.56, -2.31, -1.06]) {
    floor("wardrobe", "西侧连续衣柜", -4.94, z, Math.PI / 2);
  }
  floor("fullmirror", "衣帽间试衣镜", -2.48, -3.94);
  floor("stool", "衣帽间换衣坐凳", -3.15, -2.78);
  floor("basket", "衣帽间衣物篮", -4.81, -0.07);
  api.place({
    assetId: api.asset("pendant"), name: "衣帽间柔光灯",
    position: api.ceilingPoint(-3.55, -2.15, 0.55, 0.12),
    dimensions: [0.7, 0.55, 0.7], role: "functional"
  });

  // 主导关系：布艺大床与橡木床头背景。背景背后保留北侧连续通道。
  const bedAnchor = { x: 1.35, z: -2.48 };
  floor("headpanel", "独立橡木床头背景", bedAnchor.x, -3.94);
  floor("rug", "主卧羊毛地毯", bedAnchor.x, -1.96);
  floor("bed", "主卧双人床", bedAnchor.x, bedAnchor.z);
  for (const side of [-1, 1]) {
    const nx = bedAnchor.x + side * (2.25 / 2 + relation.bedsideGap + 0.65 / 2);
    const table = floor("nightstand", side < 0 ? "左床头柜" : "右床头柜", nx, -3.14);
    supported("tablelamp", table, [0, -0.025]);
  }
  const benchZ = bedAnchor.z + 2.45 / 2 + relation.benchFromBed + 0.48 / 2;
  const bench = floor("bench", "床尾长凳", bedAnchor.x, benchZ);
  supported("books", bench, [-0.5, 0]);
  api.place({
    assetId: api.asset("pendant"), name: "主卧纸艺吊灯",
    position: api.ceilingPoint(bedAnchor.x, -1.8, 0.55, 0.22),
    dimensions: dims.pendant, role: "functional"
  });

  // 阅读角：两个座椅围绕共用茶几，距桌沿约0.39米。
  const reading = { x: -1.05, z: 3.05 };
