    const old = existing.find(o => o.kind === "door" && o.wall === wall);
    const width = old && Number.isFinite(old.width) ? old.width : 2.4;
    const height = old && Number.isFinite(old.height) ? old.height : 2.85;
    const id = old ? old.id : api.opening({
      id: wall === "south" ? "main-lobby-entry" : "banquet-hall-passage",
      kind: "door", wall, offset: 0, bottom: 0, width, height
    });
    if (id !== undefined) {
      api.place({
        assetId: api.asset(assets.door), roomOpeningId: id,
        dimensions: [width, height, 0.14], role: "functional"
      });
    }
  }
  const southWindows = existing.filter(o => o.kind === "window" && o.wall === "south");
  if (southWindows.length) {
    for (const w of southWindows) {
      api.place({
        assetId: api.asset(assets.window), roomOpeningId: w.id,
        dimensions: [w.width || 4.4, w.height || 3.05, 0.12], role: "functional"
      });
    }
  } else {
    for (const offset of [-9.2, -4.45, 4.45, 9.2]) {
      const blocked = existing.some(o =>
        o.wall === "south" &&
        Math.abs((o.offset || 0) - offset) < ((o.width || 1.2) + 4.3) / 2 + 0.15
      );
      if (blocked) continue;
      const id = api.opening({
        id: "south-daylight-" + offset, kind: "window",
        wall: "south", offset, bottom: 0.42, width: 4.3, height: 3.12
      });
      api.place({
        assetId: api.asset(assets.window), roomOpeningId: id,
        dimensions: [4.3, 3.12, 0.12], role: "functional"
      });
    }
  }

  // 开放大堂不增加实墙；前台屏风形成焦点，低吧台限定服务边界。
  const reception = zones.reception;
  put("backdrop", reception.x, -6.2, 0, "前台品牌屏风");
  const desk = put("reception", reception.x, reception.z, 0, "双席接待前台");
  for (const dx of [-1.45, 1.45]) {
    put("taskchair", reception.x + dx, -5.65, 0, "面向来客的接待工作椅");
  }
  on("vase", desk, -2.1, 0);
  on("tablelamp", desk, 2.0, 0);
  on("menu", desk, 0.5, 0.08);
  put("luggage", -10.0, -4.95, 0, "礼宾行李车");
  put("plant", -10.0, -0.8, 0, "会客区入口绿植");

  // 大堂主焦点：相向的长沙发、中央石茶几与横向扶手椅。
  const lounge = zones.lounge;
  put("rug", lounge.x, lounge.z);
  put("sofa", lounge.x, 4.0, Math.PI, "朝向会客中心的南侧沙发");
  put("sofa", lounge.x, 0.0, 0, "朝向会客中心的北侧沙发");
  const coffee = put("coffee", lounge.x, lounge.z);
  on("tea", coffee, -0.48, 0);
  on("books", coffee, 0.55, 0.06);
  facingPoint("armchair", -8.8, 1.95, lounge.x, lounge.z, "西侧会客椅");
  facingPoint("armchair", -3.3, 1.95, lounge.x, lounge.z, "东侧会客椅");
  for (const x of [-8.55, -3.55]) {
    const table = put("side", x, 4.05);
    on("tablelamp", table);
  }
  const readingTable = put("side", -9.05, 3.05, 0, "阅读边几");
  on("books", readingTable);
  put("floorlamp", -9.55, 1.1);
  overhead("pendant", lounge.x, lounge.z, 0.45);
  for (const x of [-7.7, -4.5]) overhead("pendant", x, -4.65, 0.38);

  // 水吧面向横向通道；后台工作带与公共宴会交通分开。
  const bar = zones.bar;
  put("backbar", bar.x, -6.15, 0, "背柜与酒水陈列");
  const counter = put("bar", bar.x, -4.6, 0, "全日水吧");
  for (const dx of [-2.0, -0.7, 0.7, 2.0]) {
    put("stool", bar.x + dx, -3.72, Math.PI, "朝向水吧的吧椅");
  }
  on("tea", counter, -2.2, 0);
  on("menu", counter, 0, 0.08);
  on("vase", counter, 2.45, 0);
  for (const dx of [-1.95, 0, 1.95]) {
    overhead("pendant", bar.x + dx, -4.6, 0.55);
  }

  // 四组独立餐桌，每桌四席，桌间保留通道，南侧留整条采光漫步带。
  for (const x of [4.45, 8.65]) {
    for (const z of [0.15, 3.85]) {
      const table = put("diningtable", x, z, 0, "全日餐厅四人圆桌");
      for (const [dx, dz] of [[-0.98, 0], [0.98, 0], [0, -0.98], [0, 0.98]]) {
        facingPoint("diningchair", x + dx, z + dz, x, z, "面向餐桌的餐椅");
      }
      on("vase", table, 0, 0);
      on("menu", table, 0.33, 0.12);
      overhead("pendant", x, z, 0.6);
    }
  }
  const host = put("host", 2.3, 4.5, Math.PI, "面向南入口的餐厅迎宾台");
  on("menu", host);
  const service = put("cabinet", 6.55, 1.95, Math.PI / 2, "两列餐桌间备餐柜", [1.55, 0.92, 0.48]);
  on("tea", service, -0.35, 0);
  on("menu", service, 0.45, 0);
  put("plant", 10.05, -0.95, 0, "餐厅北端绿植");

  // 外围墙面只挂艺术品；不替换、不覆盖房间原有墙面。
  for (const wall of ["west", "east"]) {
    for (const offset of [-3.8, 2.2]) {
      const frame = api.wallFrame(wall, offset, 2.95, 0.035);
      api.place({
        assetId: api.asset(assets.art),
        position: frame.point, facing: { direction: frame.inward },
        dimensions: dims.art, role: "decor",
        name: "高位砂色抽象艺术"
      });
    }
  }
  for (const z of [-5.5, -2.35, 1.4, 5.9]) {
    overhead("ceiling", 0, z, 0);
  }
  for (const x of [-8.7, -4.3, 4.3, 8.7]) {
    overhead("ceiling", x, 6.3, 0);
  }
}

